function dropItem(boss=false,elite=false){const type=['weapon','armor','charm'][random(0,2)],roll=Math.random(),ri=boss?Math.min(4,roll<.3?4:roll<.68?3:2):elite?(roll<.08?3:roll<.38?2:1):(roll<.04?2:roll<.23?1:0),rarity=rarities[ri],tier=3;const names=gearNames[type],item={id:`i${Date.now()}${random(10,99)}`,type,name:names[random(0,names.length-1)],rarity,tier,upgrade:0};state.inventory.push(item);$('#loot-dot').classList.remove('hidden');floatText(`${rarityNames[rarity]} Beute!`,'heal',.5,.2);if(boss)combatLog(`Bossbeute: ${item.name} · ${rarityNames[rarity]}`)}
function drawBurst(){attackFlash=.7;shake=.22}
function openPanel(which){
  const titles={world:'Weltkarte',character:'Dein Held',inventory:'Beute & Ausrüstung',forge:'Aether-Schmiede',more:'Aetheria'};$('#drawer-title').textContent=titles[which]||'Aetheria';$('#drawer-kicker').textContent=which==='world'?'ERKUNDE AETHERIA':'DEIN ABENTEUER';$('#panel-backdrop').classList.remove('hidden');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.panel===which));renderPanel(which)}
function closePanel(){$('#panel-backdrop').classList.add('hidden');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.panel==='world'));save()}
function renderPanel(which){const el=$('#drawer-content');if(which==='world')el.innerHTML=worldPanel();else if(which==='character')el.innerHTML=characterPanel();else if(which==='inventory')el.innerHTML=inventoryPanel();else if(which==='forge')el.innerHTML=forgePanel();else el.innerHTML=morePanel();bindPanel(which)}
function worldPanel(){return `<div class="section-caption">DIE RISSWELT · WÄHLE DEIN ZIEL</div>${zones.map((z,i)=>{const locked=state.hero.level<z.level;return `<div class="zone-card ${i===state.zone?'selected':''} ${locked?'locked':''}" data-zone="${i}"><span class="zone-icon">${z.symbol}</span><div class="zone-info"><strong>${z.name}</strong><small>${z.sub} · ${z.creatures[0]}, ${z.creatures[1]}</small></div><span class="zone-level">ST. ${z.level}+</span><span class="zone-lock">${locked?'⌑':i===state.zone?'✦':'→'}</span></div>`}).join('')}<div class="dungeon-card"><h3>♜ &nbsp; Spiegelbruch-Dungeon</h3><p>Eine instabile Dimension. Besiege drei Wellen und stelle dich dem Risswächter. Tägliche Belohnung: Materialien & seltene Beute.</p><button id="dungeon-enter">DUNGEON BETRETEN · 3 WELLEN</button></div><p class="muted-copy">Weltbosse erscheinen in jedem Gebiet. Besiege sie für garantiert seltene Beute und Schmiedematerialien.</p>`}
function characterPanel(){const h=state.hero,s=statTotals();return `<div class="hero-summary"><div class="hero-portrait">${classes[h.class].icon}</div><div><h3>${escapeHTML(h.name)}</h3><p>${h.faction} · ${h.gender==='female'?'Weiblich':'Männlich'} ${h.class}</p><p>${zone().name}</p></div><div class="summary-level">${h.level}<small>LEVEL</small></div></div><div class="section-caption">KAMPFWERTE</div><div class="stats-grid"><div class="stat-card"><span>♥ Vitalität</span><b>${h.maxHp}</b></div><div class="stat-card"><span>✧ Mana</span><b>${h.maxMp}</b></div><div class="stat-card"><span>⚔ Angriff</span><b>${s.attack}</b></div><div class="stat-card"><span>⬟ Verteidigung</span><b>${s.def}</b></div><div class="stat-card"><span>✦ Kritische Chance</span><b>${s.crit}%</b></div><div class="stat-card"><span>♜ Besiegte Gegner</span><b>${state.kills}</b></div></div><div class="section-caption" style="margin-top:17px">FORTSCHRITT</div><div class="progress-card"><div class="progress-heading"><span>Erfahrung</span><strong>${h.xp} / ${h.xpNext} EP</strong></div><div class="progress-bar"><span style="width:${clamp(h.xp/h.xpNext*100,0,100)}%"></span></div></div><div class="info-card"><div class="progress-heading"><span>Fähigkeiten · Rang ${h.skillLevel}</span><strong>${h.class}</strong></div><p class="muted-copy">Deine Fähigkeiten werden mit jedem Level stärker. Nutze <b>${classes[h.class].skill1}</b> und <b>${classes[h.class].skill2}</b> im Kampf.</p></div><div class="section-caption">AUSGERÜSTET</div>${equipmentRows()}`}
function equipmentRows(){return ['weapon','armor','charm'].map(t=>{const it=state.inventory.find(x=>x.id===state.equipment[t]);return `<div class="item-row"><span class="item-icon">${typeIcon(t)}</span><div class="item-row-main"><strong>${t==='weapon'?'Waffe':t==='armor'?'Rüstung':'Zubehör'} · ${it?`<span class="rarity-text-${it.rarity.toLowerCase()}">${it.name}</span>`:'Leer'}</strong><small>${it?`${rarityNames[it.rarity]} · T${it.tier} · +${itemPower(it)} Stärke`:'Öffne Beute, um Ausrüstung anzulegen'}</small></div></div>`}).join('')}
function inventoryPanel(){const items=state.inventory;return `<div class="section-caption">AUSRÜSTUNG · ${items.length} GEGENSTÄNDE</div><div class="item-grid">${items.length?items.map(it=>`<button class="item-slot rarity-${it.rarity.toLowerCase()} ${Object.values(state.equipment).includes(it.id)?'equipped':''}" data-item="${it.id}" title="${it.name}"><span class="item-icon">${typeIcon(it.type)}</span><small>${it.name}</small><small class="rarity-text-${it.rarity.toLowerCase()}">${rarityNames[it.rarity]} T${it.tier}</small></button>`).join(''):`<div class="empty-state" style="grid-column:1/-1"><span>◇</span>Keine Ausrüstung gefunden.<br>Besiege Monster, um Beute zu erhalten.</div>`}</div><div id="item-details"></div><div class="section-caption" style="margin-top:18px">AUSRÜSTUNG ANLEGEN</div>${equipmentRows()}<div class="info-card"><div class="progress-heading"><span>Gold</span><strong>◈ ${state.coins}</strong></div><p class="muted-copy">Beute findest du in der Wildnis, bei Elitegegnern und in Dungeons.</p></div>`}
function forgePanel(){return `<div class="section-caption">FUSION · 4 IDENTISCHE GEGENSTÄNDE</div><div class="info-card"><p class="muted-copy" style="margin:0">Die Fusion verbraucht vier Ausrüstungsteile gleicher Stufe, Seltenheit und Gegenstandsart. T3 → T2 → T1 → nächste Seltenheit T3. Legendär wird hergestellt oder fusioniert. 4× Legendär → Mythisch · 4× Mythisch → Göttlich.</p></div><div id="fusion-area">${fusionMarkup()}</div><div class="section-caption" style="margin-top:18px">VERBESSERN</div>${state.inventory.slice(0,12).map(it=>`<div class="item-row"><span class="item-icon">${typeIcon(it.type)}</span><div class="item-row-main"><strong class="rarity-text-${it.rarity.toLowerCase()}">${it.name} · T${it.tier} +${it.upgrade}</strong><small>Stärke ${itemPower(it)} · Kosten ${25+it.upgrade*20} Gold</small></div><button data-upgrade="${it.id}">+1</button></div>`).join('')||'<div class="empty-state">Finde Ausrüstung, um sie zu verbessern.</div>'}<div class="section-caption" style="margin-top:17px">HERSTELLUNG · LEGENDÄR</div><div class="info-card"><div class="progress-heading"><span>Legendäre Ausrüstung</span><strong>◈ 250 · ✦ 12</strong></div><p class="muted-copy">Schmiede seltene Materialien zu einem zufälligen legendären Gegenstand.</p><button id="craft-btn" class="wide-action" ${state.coins<250||state.materials<12?'disabled':''}>HERSTELLEN</button></div>`}
function fusionMarkup(){const groups={};for(const it of state.inventory){const k=`${it.type}-${it.name}-${it.rarity}-${it.tier}`;(groups[k]??=[]).push(it)}const found=Object.entries(groups).find(([,arr])=>arr.length>=4);if(!found)return `<div class="forge-layout"><div class="forge-slot"><div><span class="item-icon">◇</span><strong>Fusion bereit</strong><small>Sammle 4 identische Gegenstände</small></div></div><div class="forge-plus">→</div><div class="forge-slot forge-result"><div><span class="item-icon">✧</span><strong>Nächstes Tier</strong><small>T3 → T2 → T1 → Seltenheit ↑</small></div></div></div><p class="muted-copy">Materialien: ✦ ${state.materials} · Fusion verbraucht keine Materialien.</p>`;const [key,arr]=found,first=arr[0],target=fusionTarget(first);return `<div class="forge-layout"><div class="forge-slot"><div><span class="item-icon">${typeIcon(first.type)}</span><strong>${first.name}</strong><small>${rarityNames[first.rarity]} T${first.tier} · ${arr.length}/4</small></div></div><div class="forge-plus">→</div><div class="forge-slot forge-result"><div><span class="item-icon">${typeIcon(first.type)}</span><strong>${target.name}</strong><small>${rarityNames[target.rarity]} T${target.tier}</small></div></div></div><button class="wide-action" id="fuse-btn" data-key="${escapeHTML(key)}">FUSIONIEREN · 4 GEGENSTÄNDE</button>`}
function fusionTarget(it){let ri=rarities.indexOf(it.rarity),tier=it.tier;if(tier===3)tier=2;else if(tier===2)tier=1;else{tier=3;ri=Math.min(rarities.length-1,ri+1)}return{...it,tier,rarity:rarities[ri],upgrade:0}}
