function typeIcon(type){return type==='weapon'?(state.hero.class==='Mage'?'✧':state.hero.class==='Assassin'?'⌁':'⚔'):type==='armor'?'⛨':'◈'}
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function bindPanel(which){
  if(which==='world'){$$('.zone-card').forEach(card=>card.onclick=()=>{const i=+card.dataset.zone;if(state.hero.level<zones[i].level){showToast(`Freigabe ab Level ${zones[i].level}`);return}state.zone=i;state.playerX=.28;updateZone();spawnEnemy(false);renderPanel('world');save();showToast(`${zone().name} betreten`)});const d=$('#dungeon-enter');if(d)d.onclick=()=>{state.dungeon={left:3};closePanel();spawnEnemy(false);state.enemy.rank='elite';state.enemy.name='Dungeon-Wächter';state.enemy.maxHp=Math.round(state.enemy.maxHp*1.7);state.enemy.hp=state.enemy.maxHp;updateEnemyHUD();showWave('DUNGEON · WELLE 1','Drei Wellen warten im Spiegelbruch');save()}}
  if(which==='inventory'){$$('.item-slot').forEach(b=>b.onclick=()=>showItemDetails(b.dataset.item))}
  if(which==='forge'){$$('[data-upgrade]').forEach(b=>b.onclick=()=>upgradeItem(b.dataset.upgrade));const f=$('#fuse-btn');if(f)f.onclick=()=>fuse(f.dataset.key);const c=$('#craft-btn');if(c)c.onclick=craftLegendary}
