}
function showItemDetails(id){const it=state.inventory.find(x=>x.id===id);if(!it)return;const d=$('#item-details');d.innerHTML=`<div class="info-card"><div class="progress-heading"><strong class="rarity-text-${it.rarity.toLowerCase()}">${it.name}</strong><strong>${rarityNames[it.rarity]} · T${it.tier}</strong></div><p class="muted-copy">${it.type==='weapon'?'Waffe':it.type==='armor'?'Rüstung':'Zubehör'} · Stärke +${itemPower(it)} · Verbesserung +${it.upgrade}</p><button class="small-action" id="equip-selected">${Object.values(state.equipment).includes(it.id)?'AUSGERÜSTET':'AUSRÜSTEN'}</button></div>`;$('#equip-selected').onclick=()=>equip(it.id)}
function equip(id){const it=state.inventory.find(x=>x.id===id);if(!it)return;state.equipment[it.type]=id;renderPanel('inventory');updateHUD();save();showToast(`${it.name} ausgerüstet`)}
function upgradeItem(id){const it=state.inventory.find(x=>x.id===id);if(!it)return;const cost=25+it.upgrade*20;if(state.coins<cost){showToast('Nicht genug Gold');return}state.coins-=cost;it.upgrade++;renderPanel('forge');updateHUD();save();showToast(`${it.name} verbessert`)}
