function craftLegendary(){if(state.coins<250||state.materials<12)return;state.coins-=250;state.materials-=12;const type=['weapon','armor','charm'][random(0,2)],it={id:`i${Date.now()}`,type,name:gearNames[type][random(0,4)],rarity:'Legendary',tier:3,upgrade:0};state.inventory.push(it);renderPanel('forge');save();showToast('Legendärer Gegenstand geschmiedet!')}

